import{_ as t,c as o,o as a,a2 as i}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"Set Gomoku as the default SGF viewer","description":"","frontmatter":{},"headers":[],"relativePath":"guide/set-default-image-viewer.md","filePath":"guide/set-default-image-viewer.md","lastUpdated":1780466351000}'),n={name:"guide/set-default-image-viewer.md"};function s(r,e,l,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="set-gomoku-as-the-default-sgf-viewer" tabindex="-1">Set Gomoku as the default SGF viewer <a class="header-anchor" href="#set-gomoku-as-the-default-sgf-viewer" aria-label="Permalink to &quot;Set Gomoku as the default SGF viewer&quot;">​</a></h1><p>If you want Gomoku to open <code>.sgf</code> (game record) files by default, follow these steps.</p><h2 id="step-1-—-find-a-sgf-file-in-finder" tabindex="-1">Step 1 — Find a <code>.sgf</code> file in Finder <a class="header-anchor" href="#step-1-—-find-a-sgf-file-in-finder" aria-label="Permalink to &quot;Step 1 — Find a `.sgf` file in Finder&quot;">​</a></h2><p>Locate any <code>.sgf</code> file in Finder, right-click it and choose <strong>Get Info</strong>.</p><h2 id="step-2-—-choose-open-with" tabindex="-1">Step 2 — Choose “Open with” <a class="header-anchor" href="#step-2-—-choose-open-with" aria-label="Permalink to &quot;Step 2 — Choose “Open with”&quot;">​</a></h2><p>In the <strong>Get Info</strong> panel expand the <strong>Open with</strong> section and select <strong>Gomoku</strong> from the app list.</p><h2 id="step-3-—-change-all" tabindex="-1">Step 3 — Change All <a class="header-anchor" href="#step-3-—-change-all" aria-label="Permalink to &quot;Step 3 — Change All&quot;">​</a></h2><p>Click <strong>Change All…</strong> to make Gomoku the default application for all <code>.sgf</code> files, then confirm.</p><h2 id="if-gomoku-is-not-listed" tabindex="-1">If Gomoku is not listed <a class="header-anchor" href="#if-gomoku-is-not-listed" aria-label="Permalink to &quot;If Gomoku is not listed&quot;">​</a></h2><p>If Gomoku does not appear in the <strong>Open with</strong> menu:</p><ol><li>Click <strong>Other…</strong> in the <strong>Open with</strong> dropdown</li><li>Navigate to the <code>Applications</code> folder and select <code>Gomoku.app</code></li><li>Ensure <strong>Always Open With</strong> is checked, then click <strong>Open</strong></li></ol><h2 id="revert-the-default" tabindex="-1">Revert the default <a class="header-anchor" href="#revert-the-default" aria-label="Permalink to &quot;Revert the default&quot;">​</a></h2><p>To change the default again, repeat the steps above and select a different app, then <strong>Change All…</strong>.</p><p>This will make opening <code>.sgf</code> files in Finder double‑click open them directly in Gomoku.</p>',14)])])}const g=t(n,[["render",s]]);export{c as __pageData,g as default};
